def can_tile_board(board: List[str]) -> bool:
    n = len(board)

    def is_valid(x: int, y: int) -> bool:
        return 0 <= x < n and 0 <= y < n

    def count_free_neighbors(x: int, y: int) -> int:
        return sum(1 for dx, dy in [(0, 1), (1, 0), (0, -1), (-1, 0)]
                   if is_valid(x + dx, y + dy) and board[x + dx][y + dy] == '.')

    def dfs(x: int, y: int) -> bool:
        if x == n:
            return True
        if y == n:
            return dfs(x + 1, 0)
        if board[x][y] == '#':
            return dfs(x, y + 1)

        for i in range(5):
            for j in range(5):
                if i == 2 and j == 2:
                    continue
                nx, ny = x + i - 2, y + j - 2
                if is_valid(nx, ny) and board[nx][ny] == '.':
                    if count_free_neighbors(nx, ny) < 2:
                        continue
                    board[nx] = board[nx][:ny] + '#' + board[nx][ny+1:]
                    if dfs(x, y + 1):
                        return True
                    board[nx] = board[nx][:ny] + '.' + board[nx][ny+1:]
        return False

    return dfs(0, 0)

