    from itertools import product

    def is_valid(x, y, piece):
        for dx, dy in piece:
            nx, ny = x + dx, y + dy
            if nx < 0 or nx >= n or ny < 0 or ny >= n or board[nx][ny] == '#':
                return False
        return True

    def place_piece(x, y, piece, mark):
        for dx, dy in piece:
            board[x + dx][y + dy] = mark

    def backtrack(free_cells):
        if not free_cells:
            return True
        x, y = free_cells.pop()
        if board[x][y] == '#':
            return False
        for piece in pieces:
            if is_valid(x, y, piece):
                place_piece(x, y, piece, '#')
                if backtrack(free_cells):
                    return True
                place_piece(x, y, piece, '.')
        free_cells.add((x, y))
        return False

    # Define the piece shapes
    pieces = [
        [(0, 0), (0, 1), (0, 2), (0, 3), (1, 2)],  # Top row
        [(0, 0), (0, 1), (1, 0), (1, 1), (2, 1)],  # Right column
        [(0, 0), (0, 1), (1, 1), (1, 2), (2, 0)],  # Bottom row
        [(0, 0), (0, 1), (1, 0), (2, 0), (2, 1)],  # Left column
        [(0, 1), (1, 0), (1, 1), (2, 0), (2, 1)],  # Center piece
    ]

    free_cells = {(i, j) for i, j in product(range(n), repeat=2) if board[i][j] == '.'}
    return 'YES' if backtrack(free_cells) else 'NO'

